elements.variants_sample:
HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { DialogBody() { Text("Content"); Button("Action") }.variant("help"); Text("help").font(.caption).foregroundStyle(.secondary) }
}

HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { FileIcon("Title").variant("icons"); Text("icons").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { FileIcon("Title").variant("tiles"); Text("tiles").font(.caption).foregroundStyle(.secondary) }
}

HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { ListView(columns: ["Name", "Status"], rows: [["Ana Lima", "Active"], ["Ben Okafor", "Away"]]).variant("details"); Text("details").font(.caption).foregroundStyle(.secondary) }
}

HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { ProgressBar("Label").variant("normal"); Text("normal").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { ProgressBar("Label").variant("paused"); Text("paused").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { ProgressBar("Label").variant("error"); Text("error").font(.caption).foregroundStyle(.secondary) }
}

HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { PushButton("Label").variant("default"); Text("default").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { PushButton("Label").variant("standard"); Text("standard").font(.caption).foregroundStyle(.secondary) }
}

HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { Window("Title") { Text("Content"); Button("Action") }.variant("active"); Text("active").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Window("Title") { Text("Content"); Button("Action") }.variant("inactive"); Text("inactive").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Window("Title") { Text("Content"); Button("Action") }.variant("dialog"); Text("dialog").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Window("Title") { Text("Content"); Button("Action") }.variant("tool"); Text("tool").font(.caption).foregroundStyle(.secondary) }
}

